\label{def:holder}
Let $\boldsymbol{\beta}=(\beta_1,\ldots,\beta_m)\in(0,\infty)^m$ and $L>0$. A function $g:\mathbb{R}^m\to\mathbb{R}$ belongs to the anisotropic H\"older class $\mathbb{H}_m(\boldsymbol{\beta},L)$ if, for every $k=1,\ldots,m$, the derivatives $D_k^l g$, $0\le l\le \lfloor \beta_k\rfloor$, exist and are continuous, and
\begin{gather*}
    \|D_k^l g\|_\infty\le L,\qquad 0\le l\le\lfloor \beta_k\rfloor,\\
    \big|D_k^{\lfloor \beta_k\rfloor}g(z+\tau e_k)-D_k^{\lfloor \beta_k\rfloor}g(z)\big|\le L|\tau|^{\beta_k-\lfloor \beta_k\rfloor}\qquad\forall z\in\mathbb{R}^m,\ \tau\in\mathbb{R}.
\end{gather*}
If $\beta_1=\cdots=\beta_m=\beta$ we write $\mathbb{H}_m(\beta,L)$.

\label{lem:KLP}
Let $\mathbb{F}$ be a nonempty class of functions and $t\in\mathbb{R}^d$. Assume that, for all $n$ large enough, there exist $N_n\in\mathbb{N}$, $c>1$, $\lambda_n>0$ and $F_0,F_1,\ldots,F_{N_n}\in\mathbb{F}$ such that
\begin{gather}
    |F_j(t)-F_0(t)|=\lambda_n,\qquad j=1,\ldots,N_n, \label{eq:lem1}\\
    \mathbb{E}^{(n)}_{F_0}\Big(\frac{1}{N_n}\sum_{j=1}^{N_n}Z(F_j,F_0)\Big)^2\le c. \label{eq:lem2}
\end{gather}
Then, for every $r\ge1$ and all $n$ large enough,
\[
    \inf_{\tilde F}\sup_{F\in\mathbb{F}}\Big(\mathbb{E}^{(n)}_{F}\big|\tilde F(t)-F(t)\big|^r\Big)^{1/r}\ \ge\ \frac12\Big[1-\sqrt{\frac{c-1}{c+3}}\,\Big]\lambda_n.
\]
